//! Differential tests against Go bbolt v1.3.12 through the `boltdump`
//! oracle: databases generated by Go are dumped by Go and by this crate and
//! compared byte for byte, cursors are compared op for op, bucket stats
//! field for field, and the file lock is checked against a Go process
//! holding the database open read-write.
//!
//! Skipped (with a notice) without a Go toolchain unless
//! `PURSE_REQUIRE_ORACLE` is set.

mod common;

use std::path::Path;
use std::time::{Duration, Instant};

use purse_boltread::{Bucket, Db, Error, dump};
use purse_testutil::serde_json::{Value, json};
use purse_testutil::{Oracle, SplitMix64, hex, oracle_or_skip};

fn path_json(path: &[Vec<u8>]) -> Value {
    Value::Array(path.iter().map(|c| Value::String(hex(c))).collect())
}

/// Reports the first differing line of two dumps.
fn assert_same_dump(go: &[u8], rust: &[u8], what: &str) {
    if go == rust {
        return;
    }
    let mut gl = go.split(|&b| b == b'\n');
    let mut rl = rust.split(|&b| b == b'\n');
    for n in 1.. {
        match (gl.next(), rl.next()) {
            (None, None) => break,
            (g, r) if g == r => {}
            (g, r) => panic!(
                "{what}: dumps differ at line {n}:\n  go:   {:.200}\n  rust: {:.200}",
                String::from_utf8_lossy(g.unwrap_or_default()),
                String::from_utf8_lossy(r.unwrap_or_default())
            ),
        }
    }
    panic!("{what}: dumps differ");
}

/// Dumps `path` with Go and with Rust and compares them; returns the Rust
/// database for further checks.
fn compare_dumps(oracle: &mut Oracle, path: &Path, what: &str) -> Db {
    let go_out = path.with_extension("go.dump");
    let rs_out = path.with_extension("rs.dump");
    let before = common::file_bytes(path);
    let g = oracle.call(
        "dump",
        json!({"path": path, "out": go_out, "preload_freelist": true}),
    );
    let db = Db::open(path).unwrap_or_else(|e| panic!("{what}: open: {e}"));
    let mut f = std::fs::File::create(&rs_out).expect("create dump");
    let s = dump(&db, &mut f).unwrap_or_else(|e| panic!("{what}: dump: {e}"));
    drop(f);
    let go = common::file_bytes(&go_out);
    let rust = common::file_bytes(&rs_out);
    assert_same_dump(&go, &rust, what);
    assert_eq!(
        s.sha256_hex(),
        g["sha256"].as_str().expect("sha256"),
        "{what}"
    );
    assert_eq!(s.entries, g["entries"].as_u64().expect("entries"), "{what}");
    assert_eq!(
        db.meta().txid,
        g["txid"].as_u64().expect("txid"),
        "{what}: txid"
    );
    assert_eq!(
        u64::from(db.page_size()),
        g["page_size"].as_u64().expect("page_size"),
        "{what}"
    );
    assert_eq!(db.meta().pgid, g["pgid"].as_u64().expect("pgid"), "{what}");
    let free = db.freelist().expect("freelist").expect("synced");
    assert_eq!(
        free.len() as u64,
        g["free_page_n"].as_u64().expect("free_page_n"),
        "{what}: freelist"
    );
    assert_eq!(common::file_bytes(path), before, "{what}: file changed");
    let _ = std::fs::remove_file(go_out);
    let _ = std::fs::remove_file(rs_out);
    eprintln!(
        "{what}: {} bytes, page size {}, txid {}, {} entries, {} free pages: identical",
        db.file_len(),
        db.page_size(),
        db.meta().txid,
        s.entries,
        free.len()
    );
    db
}

/// A seek target of one of the interesting kinds relative to `keys`.
fn seek_target(keys: &[Vec<u8>], rng: &mut SplitMix64) -> Vec<u8> {
    let pick =
        |rng: &mut SplitMix64| -> Vec<u8> { keys[rng.below(keys.len() as u64) as usize].clone() };
    if keys.is_empty() {
        let n = rng.below(8) as usize;
        return rng.bytes(n);
    }
    match rng.below(9) {
        // Before the first key.
        0 => Vec::new(),
        1 => {
            let mut k = keys[0].clone();
            k.pop();
            k
        }
        // After the last key.
        2 => {
            let mut k = keys[keys.len().saturating_sub(1)].clone();
            k.push(0xff);
            k
        }
        3 => vec![0xff; keys[keys.len().saturating_sub(1)].len().saturating_add(1)],
        // Exact.
        4 | 5 => pick(rng),
        // Between a key and its successor.
        6 => {
            let mut k = pick(rng);
            k.push(rng.below(256) as u8);
            k
        }
        7 => {
            let mut k = pick(rng);
            if let Some(b) = k.last_mut() {
                *b = b.wrapping_sub(1);
            }
            k
        }
        _ => {
            let n = (rng.below(40) as usize).saturating_add(1);
            rng.bytes(n)
        }
    }
}

/// Runs a random cursor script on `path_parts` through Go and Rust.
fn compare_cursor(
    oracle: &mut Oracle,
    file: &Path,
    b: &Bucket<'_>,
    path: &[Vec<u8>],
    rng: &mut SplitMix64,
    n: usize,
) {
    let keys: Vec<Vec<u8>> = b.iter().map(|i| i.expect("item").key().to_vec()).collect();
    let mut ops: Vec<(String, Vec<u8>)> = vec![("next".into(), vec![]), ("prev".into(), vec![])];
    // Fixed edge scripts first.
    for s in [
        &["last", "next", "next", "prev", "prev"][..],
        &["first", "prev", "prev", "next", "next"],
        &["seekmax", "prev", "prev", "next", "next", "next"],
        &["seekmax", "next", "prev"],
        &["seekmin", "prev", "next"],
    ] {
        for op in s {
            ops.push(match *op {
                "seekmax" => ("seek".into(), vec![0xff; 64]),
                "seekmin" => ("seek".into(), vec![]),
                o => (o.into(), vec![]),
            });
        }
    }
    for _ in 0..n {
        let r = rng.below(100);
        let op = match r {
            0..25 => ("seek".into(), seek_target(&keys, rng)),
            25..50 => ("next".into(), vec![]),
            50..72 => ("prev".into(), vec![]),
            72..77 => ("first".into(), vec![]),
            77..82 => ("last".into(), vec![]),
            82..95 => ("get".into(), seek_target(&keys, rng)),
            _ => ("bucket".into(), seek_target(&keys, rng)),
        };
        ops.push(op);
    }
    let go = oracle.call(
        "cursor",
        json!({
            "path": file,
            "bucket": path_json(path),
            "ops": ops.iter().map(|(op, k)| json!({"op": op, "key": hex(k)})).collect::<Vec<_>>(),
        }),
    );
    let go = go.as_array().expect("array");
    assert_eq!(go.len(), ops.len());
    let mut c = b.cursor();
    for (i, ((op, key), want)) in ops.iter().zip(go).enumerate() {
        let got = match op.as_str() {
            "first" => common::item_json(&c.first().expect("first")),
            "last" => common::item_json(&c.last().expect("last")),
            "next" => common::item_json(&c.next().expect("next")),
            "prev" => common::item_json(&c.prev().expect("prev")),
            "seek" => common::item_json(&c.seek(key).expect("seek")),
            "get" => json!({
                "key": hex(key),
                "value": b.get(key).expect("get").map(|v| hex(&v)),
                "bucket": false,
            }),
            "bucket" => json!({
                "key": hex(key),
                "value": null,
                "bucket": b.bucket(key).expect("bucket").is_some(),
            }),
            _ => unreachable!(),
        };
        assert_eq!(
            &got,
            want,
            "op {i} ({op} {}) in bucket {:?}",
            hex(key),
            path.iter().map(|p| hex(p)).collect::<Vec<_>>()
        );
    }
}

struct Case {
    name: &'static str,
    recipe: Value,
    cursor_buckets: usize,
    cursor_ops: usize,
    /// Structure the generated database must have, so the case tests what
    /// it claims to.
    want: Want,
}

#[derive(Default)]
struct Want {
    /// Levels of the deepest single bucket tree (1: a lone leaf).
    tree_depth: u64,
    overflow: bool,
    inline: bool,
    entries: u64,
    file_len: u64,
}

fn run_case(case: Case) {
    let Some(mut oracle) = oracle_or_skip("boltdump") else {
        return;
    };
    let t = Instant::now();
    let mut rng = SplitMix64::from_env(case.name);
    let dir = common::scratch(&format!("oracle-{}", case.name));
    let path = dir.join(format!("{}.db", case.name));
    let seed = rng.next_u64();
    let g = oracle.call(
        "generate",
        json!({"path": path, "seed": seed, "recipe": case.recipe}),
    );
    eprintln!("{}: generated {g} in {:?}", case.name, t.elapsed());
    let db = compare_dumps(&mut oracle, &path, case.name);
    let metas = db.metas();
    assert!(metas[0].1 && metas[1].1, "both meta pages validate");
    assert_ne!(metas[0].0.txid, metas[1].0.txid, "both meta pages written");

    let paths = common::bucket_paths(&db);
    // What the database holds: the deepest tree of a bucket without nested
    // buckets (its stats depth is its own tree's), and the root's totals.
    let mut tree_depth = 0;
    for p in &paths {
        let s = db
            .bucket_path(p)
            .expect("lookup")
            .expect("exists")
            .stats()
            .expect("stats");
        if s.bucket_n == 1 {
            tree_depth = tree_depth.max(s.depth);
        }
    }
    let root = db.root().stats().expect("stats");
    let entries = dump(&db, &mut std::io::sink()).expect("dump").entries;
    eprintln!(
        "{}: deepest bucket tree {tree_depth} levels; root stats {root:?}",
        case.name
    );
    let w = &case.want;
    assert!(
        tree_depth >= w.tree_depth,
        "{}: tree depth {tree_depth}",
        case.name
    );
    assert!(
        !w.overflow || root.leaf_overflow_n > 0,
        "{}: no overflow pages",
        case.name
    );
    assert!(
        !w.inline || root.inline_bucket_n > 0,
        "{}: no inline buckets",
        case.name
    );
    assert!(entries >= w.entries, "{}: {entries} entries", case.name);
    assert!(db.file_len() >= w.file_len, "{}: file length", case.name);
    // Stats: the root and every bucket (or a sample of them).
    let mut sample: Vec<&Vec<Vec<u8>>> = paths.iter().collect();
    while sample.len() > 40 {
        let i = rng.below(sample.len() as u64) as usize;
        sample.swap_remove(i);
    }
    for p in &sample {
        let b = db.bucket_path(p).expect("lookup").expect("exists");
        let go = oracle.call("stats", json!({"path": path, "bucket": path_json(p)}));
        assert_eq!(
            common::stats_json(&b.stats().expect("stats")),
            go,
            "stats of {p:?}"
        );
    }
    // Cursors: the root plus a random sample.
    let mut chosen = vec![Vec::new()];
    for _ in 0..case.cursor_buckets.min(paths.len()) {
        chosen.push(paths[rng.below(paths.len() as u64) as usize].clone());
    }
    for p in &chosen {
        let b = db.bucket_path(p).expect("lookup").expect("exists");
        compare_cursor(&mut oracle, &path, &b, p, &mut rng, case.cursor_ops);
    }
    eprintln!(
        "{}: {} buckets, stats of {}, {} cursor scripts of {} ops: identical ({:?})",
        case.name,
        paths.len(),
        sample.len(),
        chosen.len(),
        case.cursor_ops,
        t.elapsed()
    );
    drop(db);
    let _ = std::fs::remove_dir_all(dir);
}

fn base(page_size: u32) -> Value {
    json!({
        "page_size": page_size,
        "commits": 3,
        "top_buckets": 3,
        "depth": 1,
        "sub_buckets": 2,
        "keys": [5, 30],
        "key_size": [1, 32],
        "value_size": [0, 100],
        "inline_buckets": 4,
        "empty_buckets": 2,
        "add_percent": 30,
        "delete_percent": 20,
        "overwrite_percent": 10,
        "drop_percent": 40,
        "seq_percent": 30,
    })
}

fn with(mut v: Value, extra: Value) -> Value {
    for (k, x) in extra.as_object().expect("object") {
        v[k] = x.clone();
    }
    v
}

#[test]
fn small_4k() {
    run_case(Case {
        name: "small-4k",
        recipe: base(4096),
        cursor_buckets: 10,
        cursor_ops: 300,
        want: Want {
            inline: true,
            ..Want::default()
        },
    });
}

