/// At least 200k keys in about 50 MB of pages.
#[test]
fn large_4k() {
    run_case(Case {
        name: "large-4k",
        recipe: with(
            base(4096),
            json!({
                "commits": 2,
                "top_buckets": 4,
                "keys": [17000, 18000],
                "key_size": [8, 40],
                "value_size": [0, 120],
                "add_percent": 5,
                "delete_percent": 5,
                "overwrite_percent": 5,
                "drop_percent": 0,
            }),
        ),
        cursor_buckets: 6,
        cursor_ops: 2000,
        want: Want {
            tree_depth: 3,
            entries: 200_000,
            file_len: 50 << 20,
            ..Want::default()
        },
    });
}

/// Every checked-in fixture dumps identically, and the recorded digests
/// and bucket stats the Go-free tests check are still Go's.
#[test]
fn fixtures_match_go() {
    let Some(mut oracle) = oracle_or_skip("boltdump") else {
        return;
    };
    let dir = common::scratch("oracle-fixtures");
    let recorded = common::recorded_digests();
    let recorded_stats = common::recorded_stats();
    let mut checked = 0;
    for d in &recorded {
        let bytes = common::fixture_bytes(&d.file);
        let path = dir.join(d.file.replace(['/', '@'], "_"));
        std::fs::write(&path, &bytes).expect("write");
        let g = oracle.call("dump", json!({"path": path}));
        assert_eq!(
            g["sha256"].as_str(),
            Some(d.sha256.as_str()),
            "{}: recorded digest",
            d.file
        );
        assert_eq!(g["entries"].as_u64(), Some(d.entries), "{}", d.file);
        assert_eq!(g["txid"].as_u64(), Some(d.txid), "{}", d.file);
        if d.file.contains('@') {
            // An older snapshot: its freelist is not loaded.
            checked += 1;
            continue;
        }
        let db = compare_dumps(&mut oracle, &path, &d.file);
        let want = &recorded_stats[&d.file];
        let mut rng = SplitMix64::from_env(&d.file);
        let paths = common::bucket_paths(&db);
        assert_eq!(paths.len(), want.len(), "{}: bucket count", d.file);
        for p in paths {
            let b = db.bucket_path(&p).expect("lookup").expect("exists");
            let go = oracle.call("stats", json!({"path": path, "bucket": path_json(&p)}));
            assert_eq!(
                go,
                want[&common::path_string(&p)],
                "{}: recorded stats {p:?}",
                d.file
            );
            assert_eq!(
                common::stats_json(&b.stats().expect("stats")),
                go,
                "{}: stats {p:?}",
                d.file
            );
            compare_cursor(&mut oracle, &path, &b, &p, &mut rng, 60);
        }
        checked += 1;
    }
    assert_eq!(checked, common::upstream_fixtures().len() + 3);
}

/// While a Go process holds the database open read-write (as dcrwallet
/// does), opening with the lock fails promptly; after it closes, the open
/// succeeds and leaves the file unchanged. While the reader is open, Go
/// cannot open the file read-write.
#[cfg(unix)]
#[test]
fn lock_against_go_writer() {
    let Some(mut oracle) = oracle_or_skip("boltdump") else {
        return;
    };
    let dir = common::scratch("oracle-lock");
    let path = dir.join("held.db");
    let original = common::frozen();
    std::fs::write(&path, &original).expect("write");

    oracle.call("hold", json!({"path": path}));
    let t = Instant::now();
    let err = Db::open(&path).expect_err("locked");
    let took = t.elapsed();
    assert!(matches!(err, Error::Locked), "got {err}");
    assert!(took < Duration::from_millis(500), "took {took:?}");
    eprintln!("locked open failed in {took:?}: {err}");
    oracle.call("release", json!({}));
    assert_eq!(
        common::file_bytes(&path),
        original,
        "Go open changed the file"
    );

    let db = Db::open(&path).expect("open after release");
    let s = dump(&db, &mut std::io::sink()).expect("dump");
    assert!(s.entries > 0);
    // dcrwallet cannot get the exclusive lock while the reader is open.
    let e = oracle
        .try_call("hold", json!({"path": path, "timeout_ms": 300}))
        .expect_err("Go must not get the lock while the reader holds it");
    assert_eq!(e.kind.as_deref(), Some("timeout"), "{e:?}");
    drop(db);
    assert_eq!(common::file_bytes(&path), original, "file changed");
    oracle.call("hold", json!({"path": path, "timeout_ms": 2000}));
    oracle.call("release", json!({}));
}

/// Windows: bbolt opens the file `O_RDWR|O_CREATE`, which Go's
/// `syscall.Open` turns into `GENERIC_READ|GENERIC_WRITE` with sharing
/// `FILE_SHARE_READ|FILE_SHARE_WRITE` (and bbolt's lock byte comes after
/// the open). So while Go holds the file our read-only open, which does not
/// share writing, fails with a sharing violation (`Locked`); and while we
/// hold it, Go's open itself fails at once with a sharing violation instead
/// of waiting for the lock.
#[cfg(windows)]
#[test]
fn lock_against_go_writer() {
    let Some(mut oracle) = oracle_or_skip("boltdump") else {
        return;
    };
    let dir = common::scratch("oracle-lock");
    let path = dir.join("held.db");
    let original = common::frozen();
    std::fs::write(&path, &original).expect("write");

    oracle.call("hold", json!({"path": path}));
    let t = Instant::now();
    let err = Db::open(&path).expect_err("locked");
    assert!(matches!(err, Error::Locked), "got {err}");
    assert!(t.elapsed() < Duration::from_millis(500));
    oracle.call("release", json!({}));

    let db = Db::open(&path).expect("open after release");
    dump(&db, &mut std::io::sink()).expect("dump");
    let e = oracle
        .try_call("hold", json!({"path": path, "timeout_ms": 300}))
        .expect_err("Go must not open the file while the reader holds it");
    assert_eq!(e.kind.as_deref(), Some("other"), "{e:?}");
    drop(db);
    assert_eq!(common::file_bytes(&path), original, "file changed");
    oracle.call("hold", json!({"path": path, "timeout_ms": 2000}));
    oracle.call("release", json!({}));
}

/// A Go reader holding the shared lock (bbolt `ReadOnly`) does not keep the
/// reader out on Unix: both read.
#[cfg(unix)]
#[test]
fn go_reader_and_rust_reader_coexist() {
    let Some(mut oracle) = oracle_or_skip("boltdump") else {
        return;
    };
    let dir = common::scratch("oracle-shared");
    let path = dir.join("shared.db");
    std::fs::write(&path, common::frozen()).expect("write");
    oracle.call("hold", json!({"path": path, "read_only": true}));
    let db = Db::open(&path).expect("open beside a Go reader");
    let s = dump(&db, &mut std::io::sink()).expect("dump");
    assert_eq!(s.sha256_hex(), common::recorded_digest("frozen-4k.db"));
    oracle.call("release", json!({}));
}

/// Windows: bbolt's read-only open still passes `O_CREATE`, which Go maps
/// to write access, so a Go reader also keeps the reader out.
#[cfg(windows)]
#[test]
fn go_reader_and_rust_reader_coexist() {
    let Some(mut oracle) = oracle_or_skip("boltdump") else {
        return;
    };
    let dir = common::scratch("oracle-shared");
    let path = dir.join("shared.db");
    std::fs::write(&path, common::frozen()).expect("write");
    oracle.call("hold", json!({"path": path, "read_only": true}));
    assert!(matches!(Db::open(&path), Err(Error::Locked)));
    oracle.call("release", json!({}));
    Db::open(&path).expect("open after the Go reader closed");
}

/// dcrwallet's own open (no lock timeout) waits while the reader is open
/// and completes once it is dropped.
#[cfg(unix)]
#[test]
fn dcrwallet_open_waits_for_the_reader() {
    let Some(mut oracle) = oracle_or_skip("boltdump") else {
        return;
    };
    let dir = common::scratch("oracle-wait");
    let path = dir.join("wait.db");
    std::fs::write(&path, common::frozen()).expect("write");
    let db = Db::open(&path).expect("open");
    oracle.call("hold_start", json!({"path": path}));
    for _ in 0..3 {
        let w = oracle.call("hold_wait", json!({"timeout_ms": 200}));
        assert_eq!(
            w["done"], false,
            "dcrwallet's open must wait for the reader"
        );
        dump(&db, &mut std::io::sink()).expect("reader still reads");
    }
    drop(db);
    let w = oracle.call("hold_wait", json!({"timeout_ms": 5000}));
    assert_eq!(
        w["done"], true,
        "dcrwallet's open completes after the reader closes"
    );
    assert!(matches!(Db::open(&path), Err(Error::Locked)));
    oracle.call("release", json!({}));
}

/// Windows: dcrwallet's open fails at once (sharing violation) instead of
/// waiting.
#[cfg(windows)]
#[test]
fn dcrwallet_open_waits_for_the_reader() {
    let Some(mut oracle) = oracle_or_skip("boltdump") else {
        return;
    };
    let dir = common::scratch("oracle-wait");
    let path = dir.join("wait.db");
    std::fs::write(&path, common::frozen()).expect("write");
    let db = Db::open(&path).expect("open");
    oracle.call("hold_start", json!({"path": path}));
    let e = oracle
        .try_call("hold_wait", json!({"timeout_ms": 5000}))
        .expect_err("Go's open fails while the reader holds the file");
    assert_eq!(e.kind.as_deref(), Some("other"), "{e:?}");
    drop(db);
}
